insert into public.content_subjects (id,title,description,sort_order,is_published) values ('science','Science','Understand the world from atoms to ecosystems.',1,true) on conflict (id) do update set title=excluded.title,description=excluded.description,sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.content_categories (id,subject_id,title,description,sort_order,is_published) values ('chemistry','science','Chemistry','Matter, atoms, bonding, acids and bases, and more',1,true) on conflict (id) do update set subject_id=excluded.subject_id,title=excluded.title,description=excluded.description,sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.content_topics (id,category_id,title,subtitle,sort_order,accent,prerequisite_topic_id,payload,is_published) values ('science.chemistry.atomic-structure','chemistry','Atomic Structure','Protons, neutrons, electrons, and atomic number',1,'cyan',null,'{"id":"science.chemistry.atomic-structure","quiz":{"questions":[{"id":"atomic-q1","prompt":"Which particle determines an element''s atomic number?","options":["Electron","Proton","Neutron","Ion"],"difficulty":"foundation","explanation":"Atomic number is defined by the number of protons in the nucleus.","correct_index":1},{"id":"atomic-q2","prompt":"Which subatomic particle has a negative charge?","options":["Proton","Neutron","Electron","Nucleus"],"difficulty":"foundation","explanation":"Electrons carry negative charge and occupy regions around the nucleus.","correct_index":2},{"id":"atomic-q3","prompt":"Where are protons and neutrons located?","options":["Electron cloud","Nucleus","Outer shell only","Between atoms"],"difficulty":"foundation","explanation":"Protons and neutrons are concentrated in the atomic nucleus.","correct_index":1},{"id":"atomic-q4","prompt":"A neutral atom has 8 protons. How many electrons does it have?","options":["4","8","10","16"],"difficulty":"foundation","explanation":"A neutral atom has equal numbers of positive protons and negative electrons.","correct_index":1},{"id":"atomic-q5","prompt":"Atoms of the same element with different neutron counts are called...","options":["Ions","Compounds","Isotopes","Molecules"],"difficulty":"foundation","explanation":"Isotopes have the same proton count but different numbers of neutrons.","correct_index":2}],"xp_per_correct":20},"order":1,"title":"Atomic Structure","accent":"cyan","lesson":{"heading":"Inside the atom","sections":[{"title":"Proton","accent":"magenta","points":["Positive electric charge","Located in the nucleus","Number of protons determines the element"],"symbol":"+"},{"title":"Neutron","accent":"cyan","points":["No electric charge","Located in the nucleus","Changes in neutron count create isotopes"],"symbol":"0"},{"title":"Electron","accent":"green","points":["Negative electric charge","Occupies regions around the nucleus","Electron changes are involved in ion formation and bonding"],"symbol":"−"}],"introduction":"Atoms are made of smaller particles. Understanding how those particles are arranged explains atomic number, charge, ions, isotopes, and much more.","completion_xp":50,"key_concept_body":"For a neutral atom, the number of electrons equals the number of protons.","key_concept_title":"Atomic number = number of protons"},"subject":"Science","category":"Chemistry","subtitle":"Protons, neutrons, electrons, and atomic number","available":true,"challenge":{"title":"Atom Builder Challenge","rounds":[{"id":"atomic-c1","prompt":"I am positive and found in the nucleus.","options":["Proton","Neutron","Electron"],"difficulty":"foundation","explanation":"A proton has positive charge and is located in the nucleus.","correct_index":0},{"id":"atomic-c2","prompt":"I have no charge and can change the isotope.","options":["Proton","Neutron","Electron"],"difficulty":"foundation","explanation":"Neutrons are uncharged, and different neutron counts create isotopes.","correct_index":1},{"id":"atomic-c3","prompt":"I am negative and occupy regions around the nucleus.","options":["Proton","Neutron","Electron"],"difficulty":"foundation","explanation":"Electrons carry negative charge and occupy regions around the nucleus.","correct_index":2}],"description":"Use each clue to identify the correct subatomic particle.","xp_per_correct":25},"schema_version":1,"prerequisite_topic_id":null}'::jsonb,true) on conflict (id) do update set category_id=excluded.category_id,title=excluded.title,subtitle=excluded.subtitle,sort_order=excluded.sort_order,accent=excluded.accent,prerequisite_topic_id=excluded.prerequisite_topic_id,payload=excluded.payload,is_published=excluded.is_published;
insert into public.content_topics (id,category_id,title,subtitle,sort_order,accent,prerequisite_topic_id,payload,is_published) values ('science.chemistry.periodic-table','chemistry','Periodic Table','Elements, groups, periods, and recurring trends',2,'green','science.chemistry.atomic-structure','{"id":"science.chemistry.periodic-table","quiz":{"questions":[{"id":"periodic-q1","prompt":"What is a horizontal row on the periodic table called?","options":["Group","Period","Family block","Series column"],"difficulty":"foundation","explanation":"A horizontal row is called a period.","correct_index":1},{"id":"periodic-q2","prompt":"Elements in the same vertical group often have what in common?","options":["Exactly the same mass","Similar chemical behavior","The same atomic number","The same number of neutrons"],"difficulty":"foundation","explanation":"Elements in the same group often have related valence-electron patterns and similar chemical behavior.","correct_index":1},{"id":"periodic-q3","prompt":"The periodic table is arranged primarily by increasing...","options":["Atomic number","Mass number","Neutron count","Density"],"difficulty":"foundation","explanation":"Modern periodic order follows increasing atomic number, which is the number of protons.","correct_index":0},{"id":"periodic-q4","prompt":"Which group contains the halogens?","options":["Group 1","Group 2","Group 17","Group 18"],"difficulty":"foundation","explanation":"The halogens occupy Group 17 of the periodic table.","correct_index":2},{"id":"periodic-q5","prompt":"Where are most metals located on the periodic table?","options":["Left and center","Upper-right corner only","Along Group 18 only","Outside the main table"],"difficulty":"foundation","explanation":"Most metals occupy the left side and center of the periodic table.","correct_index":0}],"xp_per_correct":20},"order":2,"title":"Periodic Table","accent":"green","lesson":{"heading":"Reading the periodic table","sections":[{"title":"Periods","accent":"cyan","points":["Periods are horizontal rows","Atomic number increases as you move across a period","Elements in a period show changing properties from left to right"],"symbol":"↔"},{"title":"Groups","accent":"green","points":["Groups are vertical columns","Elements in the same group often have similar chemical behavior","Main-group elements in a group often have related valence-electron patterns"],"symbol":"↕"},{"title":"Regions","accent":"orange","points":["Most metals are on the left and center","Nonmetals are mainly on the upper right","Metalloids lie near the stair-step boundary"],"symbol":"▦"}],"introduction":"The periodic table organizes elements by increasing atomic number and places elements with recurring chemical behavior into useful patterns.","completion_xp":50,"key_concept_body":"An element''s group, period, and region provide clues about its electron arrangement and chemical behavior.","key_concept_title":"Position helps predict properties"},"subject":"Science","category":"Chemistry","subtitle":"Elements, groups, periods, and recurring trends","available":true,"challenge":{"title":"Periodic Pattern Challenge","rounds":[{"id":"periodic-c1","prompt":"I am a vertical column whose elements often share similar chemical behavior.","options":["Group","Period","Atomic number"],"difficulty":"foundation","explanation":"A vertical column is a group.","correct_index":0},{"id":"periodic-c2","prompt":"I am a horizontal row across the periodic table.","options":["Group","Period","Atomic number"],"difficulty":"foundation","explanation":"A horizontal row is a period.","correct_index":1},{"id":"periodic-c3","prompt":"I equal the number of protons and determine an element''s identity.","options":["Group","Period","Atomic number"],"difficulty":"foundation","explanation":"Atomic number equals the proton count.","correct_index":2}],"description":"Match each clue to the periodic-table idea it describes.","xp_per_correct":25},"schema_version":1,"prerequisite_topic_id":"science.chemistry.atomic-structure"}'::jsonb,true) on conflict (id) do update set category_id=excluded.category_id,title=excluded.title,subtitle=excluded.subtitle,sort_order=excluded.sort_order,accent=excluded.accent,prerequisite_topic_id=excluded.prerequisite_topic_id,payload=excluded.payload,is_published=excluded.is_published;
insert into public.content_topics (id,category_id,title,subtitle,sort_order,accent,prerequisite_topic_id,payload,is_published) values ('science.chemistry.chemical-bonding','chemistry','Chemical Bonding','Ionic, covalent, and metallic bonding',3,'orange','science.chemistry.periodic-table','{"id":"science.chemistry.chemical-bonding","quiz":{"questions":[{"id":"bond-q1","prompt":"Which compound is a common example of ionic bonding?","options":["NaCl","O₂","CH₄","H₂"],"difficulty":"foundation","explanation":"Sodium chloride consists of oppositely charged ions formed after electron transfer.","correct_index":0},{"id":"bond-q2","prompt":"What happens to electrons in a covalent bond?","options":["They are shared","They disappear","They become neutrons","They remain only in one nucleus"],"difficulty":"foundation","explanation":"Covalent bonds involve sharing electron pairs between atoms.","correct_index":0},{"id":"bond-q3","prompt":"Ionic bonding is best described as attraction between...","options":["Neutral molecules only","Oppositely charged ions","Two neutron clouds","Identical nuclei"],"difficulty":"foundation","explanation":"Positive and negative ions attract electrostatically in ionic compounds.","correct_index":1},{"id":"bond-q4","prompt":"Which feature is characteristic of metallic bonding?","options":["Localized proton pairs","Delocalized valence electrons","Transferred neutrons","No electron interaction"],"difficulty":"foundation","explanation":"Metallic bonding involves valence electrons that are mobile and delocalized across many metal atoms.","correct_index":1},{"id":"bond-q5","prompt":"A bond between two nonmetal atoms is most commonly...","options":["Covalent","Metallic","Nuclear","Gravitational"],"difficulty":"foundation","explanation":"Nonmetal atoms commonly share electrons and form covalent bonds.","correct_index":0}],"xp_per_correct":20},"order":3,"title":"Chemical Bonding","accent":"orange","lesson":{"heading":"Why atoms bond","sections":[{"title":"Ionic bonding","accent":"magenta","points":["Commonly forms between metals and nonmetals","Electrons are transferred between atoms","Oppositely charged ions attract each other"],"symbol":"±"},{"title":"Covalent bonding","accent":"cyan","points":["Commonly forms between nonmetals","Atoms share one or more pairs of electrons","Shared electrons help atoms reach more stable arrangements"],"symbol":"—"},{"title":"Metallic bonding","accent":"orange","points":["Occurs among metal atoms","Valence electrons are delocalized through the metal","Mobile electrons help explain conductivity and malleability"],"symbol":"M"}],"introduction":"Chemical bonds form through interactions involving valence electrons. Different electron behaviors produce ionic, covalent, and metallic bonding.","completion_xp":50,"key_concept_body":"Electron transfer leads to ionic attraction, electron sharing forms covalent bonds, and delocalized electrons characterize metallic bonding.","key_concept_title":"Bond type depends on electron behavior"},"subject":"Science","category":"Chemistry","subtitle":"Ionic, covalent, and metallic bonding","available":true,"challenge":{"title":"Bond Type Challenge","rounds":[{"id":"bond-c1","prompt":"Electrons are transferred, producing positive and negative ions.","options":["Ionic","Covalent","Metallic"],"difficulty":"foundation","explanation":"Electron transfer and ion attraction describe ionic bonding.","correct_index":0},{"id":"bond-c2","prompt":"Two nonmetal atoms share electron pairs.","options":["Ionic","Covalent","Metallic"],"difficulty":"foundation","explanation":"Electron sharing describes covalent bonding.","correct_index":1},{"id":"bond-c3","prompt":"Many metal atoms share a mobile pool of delocalized electrons.","options":["Ionic","Covalent","Metallic"],"difficulty":"foundation","explanation":"Delocalized electrons are central to metallic bonding.","correct_index":2}],"description":"Classify each clue by its dominant bonding model.","xp_per_correct":25},"schema_version":1,"prerequisite_topic_id":"science.chemistry.periodic-table"}'::jsonb,true) on conflict (id) do update set category_id=excluded.category_id,title=excluded.title,subtitle=excluded.subtitle,sort_order=excluded.sort_order,accent=excluded.accent,prerequisite_topic_id=excluded.prerequisite_topic_id,payload=excluded.payload,is_published=excluded.is_published;
insert into public.content_topics (id,category_id,title,subtitle,sort_order,accent,prerequisite_topic_id,payload,is_published) values ('science.chemistry.acids-bases','chemistry','Acids & Bases','Proton transfer, pH, and acid–base behavior',4,'magenta','science.chemistry.chemical-bonding','{"id":"science.chemistry.acids-bases","quiz":{"questions":[{"id":"acid-q1","prompt":"In Brønsted–Lowry theory, an acid is a substance that...","options":["Donates a proton","Accepts a proton","Donates a neutron","Accepts an electron pair only"],"difficulty":"foundation","explanation":"A Brønsted–Lowry acid donates H⁺.","correct_index":0},{"id":"acid-q2","prompt":"In Brønsted–Lowry theory, a base is a substance that...","options":["Accepts a proton","Donates a proton","Creates protons","Always contains OH⁻"],"difficulty":"foundation","explanation":"A Brønsted–Lowry base accepts H⁺; it does not have to contain hydroxide.","correct_index":0},{"id":"acid-q3","prompt":"At 25 °C, which pH value is acidic?","options":["3","7","9","12"],"difficulty":"foundation","explanation":"At 25 °C, aqueous solutions with pH below 7 are acidic.","correct_index":0},{"id":"acid-q4","prompt":"At 25 °C, pure water is approximately...","options":["pH 2","pH 5","pH 7","pH 12"],"difficulty":"foundation","explanation":"Pure water is neutral and has pH about 7 at 25 °C.","correct_index":2},{"id":"acid-q5","prompt":"Which statement best distinguishes acid strength from concentration?","options":["Strength describes extent of ionization; concentration describes amount per volume","Strength and concentration always mean the same thing","Strong acids must always be concentrated","Weak acids cannot be concentrated"],"difficulty":"foundation","explanation":"Strength concerns ionization behavior, while concentration concerns how much solute is present per volume.","correct_index":0}],"xp_per_correct":20},"order":4,"title":"Acids & Bases","accent":"magenta","lesson":{"heading":"Understanding acids and bases","sections":[{"title":"Brønsted acid","accent":"magenta","points":["A Brønsted–Lowry acid donates a proton","Acids can transfer H⁺ to a base","Acid strength is related to the extent of ionization, not simply concentration"],"symbol":"H⁺"},{"title":"Brønsted base","accent":"cyan","points":["A Brønsted–Lowry base accepts a proton","Bases react with proton donors","A base may be neutral or negatively charged"],"symbol":"B"},{"title":"pH","accent":"green","points":["At 25 °C, pH below 7 is acidic","At 25 °C, pH 7 is neutral for pure water","At 25 °C, pH above 7 is basic"],"symbol":"pH"}],"introduction":"Acid–base chemistry can be described through how substances behave in water and how they transfer protons. pH provides a useful measure of acidity or basicity in aqueous solutions.","completion_xp":50,"key_concept_body":"In Brønsted–Lowry theory, acid–base reactions are proton-transfer reactions.","key_concept_title":"Acid donates H⁺; base accepts H⁺"},"subject":"Science","category":"Chemistry","subtitle":"Proton transfer, pH, and acid–base behavior","available":true,"challenge":{"title":"Acid–Base Identity Challenge","rounds":[{"id":"acid-c1","prompt":"I donate H⁺ in a Brønsted–Lowry reaction.","options":["Acid","Base","Neutral"],"difficulty":"foundation","explanation":"A proton donor is a Brønsted–Lowry acid.","correct_index":0},{"id":"acid-c2","prompt":"I accept H⁺ in a Brønsted–Lowry reaction.","options":["Acid","Base","Neutral"],"difficulty":"foundation","explanation":"A proton acceptor is a Brønsted–Lowry base.","correct_index":1},{"id":"acid-c3","prompt":"I describe pure water at about pH 7 at 25 °C.","options":["Acid","Base","Neutral"],"difficulty":"foundation","explanation":"Pure water at 25 °C is neutral at approximately pH 7.","correct_index":2}],"description":"Use each clue to identify whether it describes an acid, base, or neutral water at 25 °C.","xp_per_correct":25},"schema_version":1,"prerequisite_topic_id":"science.chemistry.chemical-bonding"}'::jsonb,true) on conflict (id) do update set category_id=excluded.category_id,title=excluded.title,subtitle=excluded.subtitle,sort_order=excluded.sort_order,accent=excluded.accent,prerequisite_topic_id=excluded.prerequisite_topic_id,payload=excluded.payload,is_published=excluded.is_published;
